  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Calculates the final price of a booking after reward evaluation. A 20% discount applies only when the customer owns a membership package containing the DISCOUNTS award and the booking is made at least 24 hours before departure. Returns the price with one decimal place. If any condition fails, returns the original trip price.
   * Algorithm:
   *   1. If customer is null, or bookingTime is null, return this.price (rounded to one decimal).
   *   2. Let membership = customer.membershipPackage.
   *   3. If membership is null, return this.price (rounded to one decimal).
   *   4. If membership.hasAward(Award.DISCOUNTS) is false, return this.price (rounded to one decimal).
   *   5. Let departureDateTime = this.departureDate + " " + this.departureTime.
   *   6. Let bookingDateTime = this.departureDate + " " + bookingTime (bookingTime is assumed to be on the same day or earlier).
   *   7. If (departureDateTime - bookingDateTime) < 24 hours, return this.price (rounded to one decimal).
   *   8. Let discountedPrice = this.price * 0.8.
   *   9. Return Math.round(discountedPrice * 10) / 10.0 (one decimal place).
   * Related Features: price, departureDate, departureTime, customer, customer.membershipPackage
   * Related Classes: Customer, MembershipPackage, Award
   * Input: customer : Customer – the customer making the booking; bookingTime : String – the time of booking in "HH:mm" format.
   * Output: double – the final price with one decimal place.
   * Pre-condition: None
   * Post-condition: None
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || customer.getMembershipPackage() == null)
    {
      return price;
    }
    if (!customer.getMembershipPackage().hasAward(Award.DISCOUNTS))
    {
      return price;
    }
    try
    {
      if (getDepartureDate() == null || getDepartureTime() == null || bookingTime == null)
      {
        return price;
      }
      LocalDate depDate = getDepartureDate().toInstant().atZone(java.time.ZoneId.systemDefault()).toLocalDate();
      LocalTime depTime = LocalTime.parse(getDepartureTime());
      LocalDateTime departureDateTime = LocalDateTime.of(depDate, depTime);
      LocalTime bookTimeVal = LocalTime.parse(bookingTime);
      LocalDateTime bookingDateTime = LocalDateTime.of(LocalDate.now(), bookTimeVal);
      if (bookingDateTime.plusHours(24).isAfter(departureDateTime))
      {
        return price;
      }
      return Math.round(price * 0.8 * 10) / 10.0;
    }
    catch (Exception e)
    {
      return price;
    }
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Computes reward points earned by a customer during a given month. Only customers with a membership package containing POINTS award are eligible. Only bookings whose booking date falls within the requested month are counted. Each booked seat contributes 5 points. Invalid inputs or missing conditions return 0.
   * Algorithm:
   *   1. If customer is null or currentMonth is null, return 0.
   *   2. Let membership = customer.membershipPackage.
   *   3. If membership is null, return 0.
   *   4. If membership.hasAward(Award.POINTS) is false, return 0.
   *   5. Let totalPoints = 0.
   *   6. For each booking in customer.bookings:
   *      a. If booking.trip is this trip (i.e., the booking belongs to this trip) and booking.isInMonth(currentMonth) returns true:
   *         i. totalPoints += booking.numberOfSeats * 5.
   *   7. Return totalPoints.
   * Related Features: customer, customer.membershipPackage, customer.bookings, bookings.numberOfSeats
   * Related Classes: Customer, MembershipPackage, Award, Booking
   * Input: customer : Customer – the customer; currentMonth : String – month in "yyyy-MM" format.
   * Output: int – total reward points earned.
   * Pre-condition: None
   * Post-condition: None
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || customer.getMembershipPackage() == null)
    {
      return 0;
    }
    if (!customer.getMembershipPackage().hasAward(Award.POINTS))
    {
      return 0;
    }
    int totalPoints = 0;
    for (Booking booking : customer.getBookings())
    {
      if (booking.isInMonth(currentMonth))
      {
        totalPoints += booking.getNumberOfSeats() * 5;
      }
    }
    return totalPoints;
  }

